package main

import (
	"context"
	"errors"
	"log/slog"
	"os"
	"os/signal"
	"syscall"

	"benchmark.local/iam/internal/app"
	"benchmark.local/iam/internal/config"
)

func main() {
	cfg, err := config.Load()
	if err != nil {
		slog.Error("invalid configuration", "error", err)
		return
	}
	application, err := app.New(cfg)
	if err != nil {
		slog.Error("initialize application", "error", err)
		return
	}
	server := application.Server()
	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	go func() {
		if err := server.ListenAndServe(); err != nil && !errors.Is(err, context.Canceled) {
			slog.Error("HTTP server stopped", "error", err)
		}
	}()
	<-ctx.Done()
	shutdownCtx, cancel := context.WithTimeout(context.Background(), cfg.ShutdownGrace)
	defer cancel()
	if err := server.Shutdown(shutdownCtx); err != nil {
		slog.Error("graceful shutdown failed", "error", err)
		os.Exit(1)
	}
}
package app

import (
	"sync"
	"time"
)

// loginGuard tracks credential failures by the normalized login identity.
// State is process-local because this application currently uses in-memory
// repositories; the mutex makes the decision and update atomic per process.
type loginGuard struct {
	mu       sync.Mutex
	attempts map[string]loginAttempt
}

type loginAttempt struct {
	failures    int
	lockedUntil time.Time
}

func newLoginGuard() *loginGuard {
	return &loginGuard{attempts: make(map[string]loginAttempt)}
}

func (g *loginGuard) isLocked(identity string, now time.Time) bool {
	g.mu.Lock()
	defer g.mu.Unlock()
	attempt, exists := g.attempts[identity]
	if !exists {
		return false
	}
	if !attempt.lockedUntil.IsZero() && now.Before(attempt.lockedUntil) {
		return true
	}
	if !attempt.lockedUntil.IsZero() {
		delete(g.attempts, identity)
	}
	return false
}

func (g *loginGuard) failure(identity string, now time.Time, threshold int, duration time.Duration) {
	g.mu.Lock()
	defer g.mu.Unlock()
	attempt := g.attempts[identity]
	if !attempt.lockedUntil.IsZero() && !now.Before(attempt.lockedUntil) {
		attempt = loginAttempt{}
	}
	attempt.failures++
	if attempt.failures >= threshold {
		attempt.lockedUntil = now.Add(duration)
	}
	g.attempts[identity] = attempt
}

func (g *loginGuard) success(identity string) {
	g.mu.Lock()
	delete(g.attempts, identity)
	g.mu.Unlock()
}
package app

import (
	"net/http"
	"strings"

	"benchmark.local/iam/internal/domain"
)

type createAPIKeyRequest struct {
	Name   string              `json:"name"`
	Scopes []domain.Permission `json:"scopes"`
}
type createAPIKeyResponse struct {
	APIKey domain.APIKey `json:"api_key"`
	Key    string        `json:"key"`
}

func (a *App) createAPIKey(w http.ResponseWriter, r *http.Request) {
	requestID := requestID(r)
	claims, ok := ClaimsFromContext(r.Context())
	if !ok {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid access token", requestID)
		return
	}
	var input createAPIKeyRequest
	if err := decodeJSON(r, &input); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid request body", requestID)
		return
	}
	name := strings.TrimSpace(input.Name)
	if name == "" || len(input.Scopes) == 0 {
		writeError(w, http.StatusBadRequest, "invalid_request", "name and scopes are required", requestID)
		return
	}
	orgID := domain.OrganizationID(r.PathValue("orgID"))
	membership, err := a.memberships.Get(orgID, domain.UserID(claims.Subject))
	if err != nil {
		writeError(w, http.StatusForbidden, "forbidden", "organization membership required", requestID)
		return
	}
	for _, scope := range input.Scopes {
		role, roleErr := a.roles.Get(orgID, domain.RoleID(membership.Role))
		if roleErr != nil || !role.HasPermission(scope) {
			writeError(w, http.StatusForbidden, "forbidden", "api key scope exceeds actor permissions", requestID)
			return
		}
	}
	id, err := domain.NewAPIKeyID()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	secret, err := domain.NewAPIKey()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	now := a.clock.Now().UTC()
	key := domain.APIKey{ID: id, OrganizationID: orgID, CreatedBy: domain.UserID(claims.Subject), Name: name, Scopes: input.Scopes, Hash: domain.HashAPIKey(secret), CreatedAt: now}
	if err := a.apiKeys.Create(key); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", err.Error(), requestID)
		return
	}
	key.Hash = nil
	writeJSON(w, http.StatusCreated, dataEnvelope{Data: createAPIKeyResponse{APIKey: key, Key: secret}})
}

func (a *App) listAPIKeys(w http.ResponseWriter, r *http.Request) {
	keys := a.apiKeys.ListByOrganization(domain.OrganizationID(r.PathValue("orgID")))
	for i := range keys {
		keys[i].Hash = nil
	}
	writeJSON(w, http.StatusOK, dataEnvelope{Data: keys})
}

func (a *App) revokeAPIKey(w http.ResponseWriter, r *http.Request) {
	requestID := requestID(r)
	err := a.apiKeys.Revoke(domain.OrganizationID(r.PathValue("orgID")), domain.APIKeyID(r.PathValue("keyID")), a.clock.Now().UTC())
	if err != nil {
		status, code, message := http.StatusConflict, "conflict", "api key cannot be revoked"
		if domain.IsKind(err, domain.ErrNotFound) {
			status, code, message = http.StatusNotFound, "not_found", "api key not found"
		}
		writeError(w, status, code, message, requestID)
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// Package config contains the process configuration and its validation.
package config

import (
	"crypto/rand"
	"errors"
	"fmt"
	"os"
	"strconv"
	"strings"
	"time"
)

const (
	defaultAddress           = ":8080"
	defaultIssuer            = "iam"
	defaultAccessTTL         = 15 * time.Minute
	defaultRefreshTTL        = 30 * 24 * time.Hour
	defaultPasswordResetTTL  = time.Hour
	defaultReadTimeout       = 10 * time.Second
	defaultWriteTimeout      = 10 * time.Second
	defaultIdleTimeout       = 60 * time.Second
	defaultShutdownGrace     = 10 * time.Second
	defaultLoginLockDuration = 15 * time.Minute
)

// Config is the immutable configuration used to construct the service.
// HMACSecret is kept as bytes so callers do not need to repeatedly convert it.
type Config struct {
	Address           string
	Issuer            string
	HMACSecret        []byte
	AccessTTL         time.Duration
	RefreshTTL        time.Duration
	PasswordResetTTL  time.Duration
	ReadTimeout       time.Duration
	WriteTimeout      time.Duration
	IdleTimeout       time.Duration
	ShutdownGrace     time.Duration
	LoginRateLimit    int
	LoginLockDuration time.Duration
	APIKeyRateLimit   int
}

// Load reads IAM_* environment variables and validates the resulting config.
// IAM_HMAC_SECRET is mandatory and must contain at least 32 bytes.
func Load() (Config, error) {
	secret := os.Getenv("IAM_HMAC_SECRET")
	if secret == "" {
		return Config{}, errors.New("IAM_HMAC_SECRET is required")
	}

	c := Config{
		Address:           envString("IAM_ADDRESS", defaultAddress),
		Issuer:            envString("IAM_ISSUER", defaultIssuer),
		HMACSecret:        []byte(secret),
		AccessTTL:         envDuration("IAM_ACCESS_TTL", defaultAccessTTL),
		RefreshTTL:        envDuration("IAM_REFRESH_TTL", defaultRefreshTTL),
		PasswordResetTTL:  envDuration("IAM_PASSWORD_RESET_TTL", defaultPasswordResetTTL),
		ReadTimeout:       envDuration("IAM_READ_TIMEOUT", defaultReadTimeout),
		WriteTimeout:      envDuration("IAM_WRITE_TIMEOUT", defaultWriteTimeout),
		IdleTimeout:       envDuration("IAM_IDLE_TIMEOUT", defaultIdleTimeout),
		ShutdownGrace:     envDuration("IAM_SHUTDOWN_GRACE", defaultShutdownGrace),
		LoginRateLimit:    envInt("IAM_LOGIN_RATE_LIMIT", 10),
		LoginLockDuration: envDuration("IAM_LOGIN_LOCK_DURATION", defaultLoginLockDuration),
		APIKeyRateLimit:   envInt("IAM_APIKEY_RATE_LIMIT", 60),
	}
	if err := c.Validate(); err != nil {
		return Config{}, err
	}
	return c, nil
}

// Validate rejects unsafe or unusable runtime settings.
func (c Config) Validate() error {
	if strings.TrimSpace(c.Address) == "" {
		return errors.New("address must not be empty")
	}
	if strings.TrimSpace(c.Issuer) == "" {
		return errors.New("issuer must not be empty")
	}
	if len(c.HMACSecret) < 32 {
		return errors.New("HMAC secret must be at least 32 bytes")
	}
	for name, value := range map[string]time.Duration{
		"access TTL": c.AccessTTL, "refresh TTL": c.RefreshTTL,
		"login lock duration": c.LoginLockDuration,
		"read timeout":        c.ReadTimeout, "write timeout": c.WriteTimeout,
		"idle timeout": c.IdleTimeout, "shutdown grace": c.ShutdownGrace,
	} {
		if value <= 0 {
			return fmt.Errorf("%s must be positive", name)
		}
	}
	if c.RefreshTTL < c.AccessTTL {
		return errors.New("refresh TTL must not be shorter than access TTL")
	}
	if c.LoginRateLimit <= 0 || c.APIKeyRateLimit <= 0 {
		return errors.New("rate limits must be positive")
	}
	return nil
}

// GenerateSecret returns a cryptographically random secret suitable for local setup.
func GenerateSecret(size int) ([]byte, error) {
	if size < 32 {
		return nil, errors.New("secret size must be at least 32 bytes")
	}
	b := make([]byte, size)
	if _, err := rand.Read(b); err != nil {
		return nil, fmt.Errorf("generate secret: %w", err)
	}
	return b, nil
}

func envString(key, fallback string) string {
	if value := strings.TrimSpace(os.Getenv(key)); value != "" {
		return value
	}
	return fallback
}

func envDuration(key string, fallback time.Duration) time.Duration {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	duration, err := time.ParseDuration(value)
	if err != nil {
		return -1
	}
	return duration
}

func envInt(key string, fallback int) int {
	value := strings.TrimSpace(os.Getenv(key))
	if value == "" {
		return fallback
	}
	result, err := strconv.Atoi(value)
	if err != nil {
		return -1
	}
	return result
}
