func decodeJSON(r *http.Request, destination any) error {
	limited := &countingReader{reader: io.LimitReader(r.Body, maxJSONBodySize+1)}
	decoder := json.NewDecoder(limited)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(destination); err != nil {
		return err
	}
	if limited.count > maxJSONBodySize {
		return errors.New("request body too large")
	}
	var extra any
	if err := decoder.Decode(&extra); !errors.Is(err, io.EOF) {
		if err == nil {
			return errors.New("multiple JSON values")
		}
		return err
	}
	if limited.count > maxJSONBodySize {
		return errors.New("request body too large")
	}
	return nil
}

type countingReader struct {
	reader io.Reader
	count  int64
}

func (r *countingReader) Read(p []byte) (int, error) {
	n, err := r.reader.Read(p)
	r.count += int64(n)
	return n, err
}

func withRequestID(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		id := requestID(r)
		r.Header.Set("X-Request-ID", id)
		w.Header().Set("X-Request-ID", id)
		next.ServeHTTP(w, r)
	})
}

func requestID(r *http.Request) string {
	if value := strings.TrimSpace(r.Header.Get("X-Request-ID")); value != "" {
		return value
	}
	var raw [16]byte
	if _, err := rand.Read(raw[:]); err == nil {
		return hex.EncodeToString(raw[:])
	}
	return "unknown"
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(value)
}

func writeError(w http.ResponseWriter, status int, code, message, requestID string) {
	writeJSON(w, status, errorEnvelope{Error: errorBody{Code: code, Message: message, RequestID: requestID}})
}
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	writeJSON(w, http.StatusOK, dataEnvelope{Data: organization})
}

func (a *App) acceptInvite(w http.ResponseWriter, r *http.Request) {
	requestID := requestID(r)
	claims, ok := ClaimsFromContext(r.Context())
	if !ok || strings.TrimSpace(claims.Subject) == "" || !domain.ValidInviteToken(r.PathValue("token")) {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid invite token", requestID)
		return
	}
	user, err := a.users.GetByID(domain.UserID(claims.Subject))
	if err != nil {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid access token", requestID)
		return
	}
	now := a.clock.Now().UTC()
	tokenHash := domain.HashInviteToken(r.PathValue("token"))
	invite, err := a.invites.GetByToken(tokenHash)
	if err != nil || !now.Before(invite.ExpiresAt) || !strings.EqualFold(user.Email, invite.Email) {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid invite token", requestID)
		return
	}
	invite, err = a.invites.Consume(tokenHash, now)
	if err != nil {
		writeError(w, http.StatusConflict, "conflict", "invite already accepted", requestID)
		return
	}
	id, err := domain.NewID()
	if err != nil {
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	membership := domain.Membership{ID: id, OrganizationID: invite.OrganizationID, UserID: user.ID, Role: invite.Role, CreatedAt: now, UpdatedAt: now}
	if err := a.memberships.Create(membership); err != nil {
		if domain.IsKind(err, domain.ErrConflict) {
			writeError(w, http.StatusConflict, "conflict", "membership already exists", requestID)
			return
		}
		writeError(w, http.StatusInternalServerError, "internal_error", "internal server error", requestID)
		return
	}
	writeJSON(w, http.StatusOK, dataEnvelope{Data: membership})
}

func (a *App) createOrganization(w http.ResponseWriter, r *http.Request) {
	requestID := requestID(r)
	claims, ok := ClaimsFromContext(r.Context())
	if !ok || strings.TrimSpace(claims.Subject) == "" {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid access token", requestID)
		return
	}
	ownerID := domain.UserID(claims.Subject)
	if _, err := a.users.GetByID(ownerID); err != nil {
		writeError(w, http.StatusUnauthorized, "unauthorized", "invalid access token", requestID)
		return
	}

	var input createOrganizationRequest
	if err := decodeJSON(r, &input); err != nil {
		writeError(w, http.StatusBadRequest, "invalid_request", "invalid request body", requestID)
		return
	}
	name := strings.TrimSpace(input.Name)
	if name == "" {
		writeError(w, http.StatusBadRequest, "invalid_request", "organization name is required", requestID)
		return
	}

package domain

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"strings"
	"time"
)

const InviteTokenBytes = 32

// Invite stores only the digest of the opaque token given to an invitee.
type Invite struct {
	ID             InviteID       `json:"id"`
	OrganizationID OrganizationID `json:"organization_id"`
	Email          string         `json:"email"`
	Role           string         `json:"role"`
	TokenHash      []byte         `json:"-"`
	InvitedBy      UserID         `json:"invited_by"`
	CreatedAt      time.Time      `json:"created_at"`
	ExpiresAt      time.Time      `json:"expires_at"`
	AcceptedAt     time.Time      `json:"accepted_at,omitempty"`
}

func NewInviteToken() (string, error) {
	var raw [InviteTokenBytes]byte
	if _, err := rand.Read(raw[:]); err != nil {
		return "", errors.New("generate invite token")
	}
	return base64.RawURLEncoding.EncodeToString(raw[:]), nil
}

func HashInviteToken(token string) []byte {
	digest := sha256.Sum256([]byte(token))
	return append([]byte(nil), digest[:]...)
}

func ValidInviteToken(token string) bool {
	if strings.TrimSpace(token) != token || token == "" {
		return false
	}
	raw, err := base64.RawURLEncoding.DecodeString(token)
	return err == nil && len(raw) == InviteTokenBytes
}
package domain

import "time"

// EmailVerificationState describes the state of a user's email address.
// Keeping this state explicit avoids inferring verification from the presence
// or absence of unrelated user data.
type EmailVerificationState string

const (
	EmailVerificationPending  EmailVerificationState = "pending"
	EmailVerificationVerified EmailVerificationState = "verified"
)

// PasswordMaterial contains only the derived password material needed for
// password verification. It deliberately has no JSON representation: this
// type must not leak through API responses, logs, or other JSON envelopes.
type PasswordMaterial struct {
	Salt       []byte
	Hash       []byte
	Iterations uint32
}

// MarshalJSON prevents accidental serialization even when PasswordMaterial is
// marshaled directly rather than as part of User.
func (PasswordMaterial) MarshalJSON() ([]byte, error) { return []byte("{}"), nil }

// User is the private domain representation of an account. PasswordMaterial
// is kept separate from the fields exposed by PublicUserProfile.
type User struct {
	ID                     UserID                 `json:"id"`
	Email                  string                 `json:"email"`
	EmailVerified          bool                   `json:"email_verified"`
	EmailVerificationState EmailVerificationState `json:"email_verification_state"`
	PasswordMaterial       PasswordMaterial       `json:"-"`
	CreatedAt              time.Time              `json:"created_at"`
	UpdatedAt              time.Time              `json:"updated_at"`
}

// PublicUserProfile is the safe representation of a user for API responses.
// It contains account identity and verification state, but no password data.
type PublicUserProfile struct {
	ID                     UserID                 `json:"id"`
	Email                  string                 `json:"email"`
	EmailVerified          bool                   `json:"email_verified"`
	EmailVerificationState EmailVerificationState `json:"email_verification_state"`
	CreatedAt              time.Time              `json:"created_at"`
}

// PublicProfile returns the user data that may be sent to a client.
func (u User) PublicProfile() PublicUserProfile {
	return PublicUserProfile{
		ID:                     u.ID,
		Email:                  u.Email,
		EmailVerified:          u.EmailVerified,
		EmailVerificationState: u.EmailVerificationState,
		CreatedAt:              u.CreatedAt,
	}
}
